window.CHEMISTRY_BANK=[{"q":"What is the electric charge of a proton?","a":"+1","d1":"-1","d2":"0","d3":"+2","explain":"Protons are positive; a +1 charge balances one electron's -1.","topic":"atoms","tier":1,"trap":"Confusing a proton with an electron, which carries -1."},{"q":"Which subatomic particle has no electric charge?","a":"Neutron","d1":"Proton","d2":"Electron","d3":"Ion","explain":"Neutrons are neutral; protons are positive and electrons negative.","topic":"atoms","tier":1,"trap":"Assuming every particle in the nucleus is charged."},{"q":"What does the atomic number of an element tell you?","a":"The number of protons","d1":"The number of neutrons","d2":"The number of electron shells","d3":"The total number of protons and neutrons","explain":"Atomic number equals the proton count; in a neutral atom it also equals the electron count.","topic":"atoms","tier":1,"trap":"Confusing atomic number with mass number."},{"q":"Where are the electrons in an atom?","a":"In shells around the nucleus","d1":"Inside the nucleus","d2":"Inside the protons","d3":"In the neutron cloud","explain":"Electrons occupy energy levels, or shells, outside the nucleus.","topic":"atoms","tier":1,"trap":"Placing electrons in the nucleus with protons and neutrons."},{"q":"What does the mass number of an atom tell you?","a":"Protons plus neutrons","d1":"Protons only","d2":"Electrons plus protons","d3":"Neutrons only","explain":"Mass number counts the nucleons: protons and neutrons.","topic":"atoms","tier":1,"trap":"Confusing mass number with atomic number."},{"q":"What is the chemical symbol for sodium?","a":"Na","d1":"S","d2":"So","d3":"N","explain":"Sodium is Na, from its Latin name natrium.","topic":"atoms","tier":1,"trap":"Using the first letter of the English name."},{"q":"What is the chemical symbol for potassium?","a":"K","d1":"P","d2":"Po","d3":"Kt","explain":"Potassium is K, from its Latin name kalium.","topic":"atoms","tier":1,"trap":"Using P, which is phosphorus."},{"q":"Which subatomic particle carries a negative charge?","a":"Electron","d1":"Proton","d2":"Neutron","d3":"Nucleus","explain":"Electrons are negative and occupy shells around the nucleus.","topic":"atoms","tier":1,"trap":"Reversing the charges of protons and electrons."},{"q":"An atom has 11 protons and 12 neutrons. What is its mass number?","a":"23","d1":"11","d2":"12","d3":"24","explain":"Mass number = 11 + 12 = 23.","topic":"atoms","tier":2,"trap":"Giving the atomic number or doubling the neutron count."},{"q":"An atom has 17 protons and 18 electrons. What is its charge?","a":"-1","d1":"+1","d2":"0","d3":"-17","explain":"17 positive protons and 18 negative electrons give a net charge of -1.","topic":"atoms","tier":2,"trap":"Subtracting in the wrong direction or ignoring the electrons."},{"q":"How many neutrons are in a carbon-14 atom? Carbon has atomic number 6.","a":"8","d1":"6","d2":"14","d3":"20","explain":"14 - 6 = 8 neutrons.","topic":"atoms","tier":2,"trap":"Reporting the mass number or the atomic number."},{"q":"How many electrons does a neutral atom with atomic number 19 have?","a":"19","d1":"39","d2":"20","d3":"18","explain":"A neutral atom has equal numbers of protons and electrons.","topic":"atoms","tier":2,"trap":"Using the mass number instead of the atomic number."},{"q":"Two isotopes of the same element differ in their number of what?","a":"Neutrons","d1":"Protons","d2":"Electrons in a neutral atom","d3":"Protons and neutrons together","explain":"Isotopes have the same proton count but different neutron counts, so different mass numbers.","topic":"atoms","tier":2,"trap":"Thinking isotopes differ in protons, which would make a different element."},{"q":"An ion has 12 protons and 10 electrons. What is its charge?","a":"2+","d1":"2-","d2":"0","d3":"10+","explain":"12 - 10 = 2 more protons, so the charge is 2+.","topic":"atoms","tier":2,"trap":"Reversing the sign or counting electrons as positive."},{"q":"What is the electron configuration of chlorine? Chlorine has atomic number 17.","a":"2,8,7","d1":"2,8,8","d2":"2,7,8","d3":"8,8,1","explain":"Shells fill 2, then 8, then 7, using 17 electrons in total.","topic":"atoms","tier":2,"trap":"Filling the outer shell to 8 instead of using the third shell correctly."},{"q":"An atom has atomic number 20 and mass number 40. How many neutrons does it have?","a":"20","d1":"40","d2":"60","d3":"18","explain":"40 - 20 = 20 neutrons.","topic":"atoms","tier":2,"trap":"Reporting the mass number or adding instead of subtracting."},{"q":"The relative atomic mass of chlorine is 35.5, not a whole number. Why?","a":"It is a weighted average of isotopes with different masses","d1":"Some chlorine atoms have half a neutron","d2":"The mass of an electron is included","d3":"The value has been rounded from 35","explain":"Chlorine is about 75% Cl-35 and 25% Cl-37, giving a weighted average of 35.5.","topic":"atoms","tier":3,"trap":"Treating a non-integer Ar as a half-particle rather than an isotope average."},{"q":"Copper has isotopes Cu-63 at 69% and Cu-65 at 31%. What is its relative atomic mass to 1 decimal place?","a":"63.6","d1":"64.0","d2":"63.0","d3":"64.5","explain":"0.69 x 63 + 0.31 x 65 = 43.47 + 20.15 = 63.62, which rounds to 63.6.","topic":"atoms","tier":3,"trap":"Taking the simple mean 64 instead of weighting by abundance."},{"q":"An atom has 16 protons and 18 neutrons. Which isotope is it?","a":"Sulfur-34","d1":"Argon-34","d2":"Sulfur-16","d3":"Oxygen-34","explain":"Atomic number 16 is sulfur; mass number is 16 + 18 = 34.","topic":"atoms","tier":3,"trap":"Reading the neutron count as the atomic number."},{"q":"An aluminium atom has atomic number 13 and forms a 3+ ion. How many electrons does the ion have?","a":"10","d1":"13","d2":"16","d3":"3","explain":"A 3+ ion has lost 3 electrons: 13 - 3 = 10.","topic":"atoms","tier":3,"trap":"Adding the lost electrons instead of subtracting them."},{"q":"An atom has the electron configuration 2,8,6. What is its atomic number?","a":"16","d1":"6","d2":"14","d3":"22","explain":"Add the electrons: 2 + 8 + 6 = 16.","topic":"atoms","tier":3,"trap":"Reading only the outer shell or adding the shell numbers."},{"q":"Potassium-39 has atomic number 19. Argon-40 has atomic number 18. Which has more neutrons?","a":"Argon-40, with 22","d1":"Potassium-39, with 20","d2":"They have the same number","d3":"Neither has neutrons","explain":"K-39 has 39 - 19 = 20 neutrons; Ar-40 has 40 - 18 = 22.","topic":"atoms","tier":3,"trap":"Assuming the larger atomic number means more neutrons."},{"q":"Magnesium has a relative atomic mass of 24.3. Which isotope is most abundant?","a":"Magnesium-24","d1":"Magnesium-25","d2":"Magnesium-23","d3":"Magnesium-26","explain":"An average of 24.3 lies just above 24, so Mg-24 dominates the mixture.","topic":"atoms","tier":3,"trap":"Picking the isotope nearest the average without checking the weighting."},{"q":"A magnesium atom with configuration 2,8,2 loses two electrons. What is its electron configuration now?","a":"2,8","d1":"2,8,2","d2":"2,6","d3":"2,8,4","explain":"Losing the two outer electrons leaves the 2,8 arrangement of Mg2+.","topic":"atoms","tier":3,"trap":"Adding electrons when the ion formed is positive."},{"q":"What is the name of Group 1?","a":"Alkali metals","d1":"Halogens","d2":"Noble gases","d3":"Transition metals","explain":"Group 1 metals such as lithium and sodium are the alkali metals.","topic":"periodic","tier":1,"trap":"Mixing up the group names."},{"q":"What is the name of Group 7?","a":"Halogens","d1":"Alkali metals","d2":"Noble gases","d3":"Alkaline earth metals","explain":"Group 7 contains fluorine, chlorine, bromine and iodine, the halogens.","topic":"periodic","tier":1,"trap":"Mixing up the group names."},{"q":"What is the name of Group 0?","a":"Noble gases","d1":"Halogens","d2":"Alkali metals","d3":"Transition metals","explain":"Group 0 contains helium, neon, argon and the other noble gases.","topic":"periodic","tier":1,"trap":"Mixing up the group names."},{"q":"Which group contains elements with full outer electron shells?","a":"Group 0","d1":"Group 1","d2":"Group 2","d3":"Group 7","explain":"Noble gases have complete outer shells, which is why they are unreactive.","topic":"periodic","tier":1,"trap":"Assuming reactive groups have full shells."},{"q":"What is the chemical symbol for iron?","a":"Fe","d1":"Ir","d2":"In","d3":"F","explain":"Iron is Fe, from its Latin name ferrum.","topic":"periodic","tier":1,"trap":"Choosing a symbol that starts with the same letters but names another element."},{"q":"What is the chemical symbol for copper?","a":"Cu","d1":"Co","d2":"Cr","d3":"C","explain":"Copper is Cu, from its Latin name cuprum.","topic":"periodic","tier":1,"trap":"Confusing Cu with Co, which is cobalt."},{"q":"Which element is a metalloid, also called a semi-metal?","a":"Silicon","d1":"Sodium","d2":"Chlorine","d3":"Iron","explain":"Silicon has properties between those of metals and non-metals.","topic":"periodic","tier":1,"trap":"Treating every element as clearly metallic or non-metallic."},{"q":"What happens to the reactivity of Group 1 metals as you go down the group?","a":"It increases","d1":"It decreases","d2":"It stays the same","d3":"It rises then falls","explain":"The outer electron is lost more easily as the atom gets larger.","topic":"periodic","tier":1,"trap":"Assuming reactivity falls down every group, as it does in Group 7."},{"q":"Why does reactivity increase down Group 1?","a":"The outer electron is further from the nucleus and lost more easily","d1":"The atoms get smaller","d2":"The nuclear charge decreases","d3":"There are fewer protons","explain":"Greater distance and extra shielding weaken the attraction holding the outer electron.","topic":"periodic","tier":2,"trap":"Reversing the size trend: atoms get larger down a group, not smaller."},{"q":"A Group 1 metal reacts with water to give a metal hydroxide and which gas?","a":"Hydrogen","d1":"Oxygen","d2":"Carbon dioxide","d3":"Chlorine","explain":"For example, 2Na + 2H2O -> 2NaOH + H2.","topic":"periodic","tier":2,"trap":"Confusing the gas with oxygen from the air."},{"q":"What happens to reactivity down Group 7?","a":"It decreases","d1":"It increases","d2":"It stays constant","d3":"It has no pattern","explain":"Larger halogen atoms attract an incoming electron less strongly.","topic":"periodic","tier":2,"trap":"Applying the Group 1 trend to the halogens."},{"q":"Which is more reactive, potassium or lithium?","a":"Potassium","d1":"Lithium","d2":"They are equally reactive","d3":"It cannot be compared","explain":"Potassium is below lithium in Group 1, so it loses its outer electron more easily.","topic":"periodic","tier":2,"trap":"Assuming the lighter metal must be more reactive."},{"q":"A Group 2 metal has two outer electrons. What ion will it form?","a":"2+","d1":"1+","d2":"2-","d3":"1-","explain":"Metals lose outer electrons, and losing two gives a 2+ ion.","topic":"periodic","tier":2,"trap":"Giving a negative charge to a metal ion."},{"q":"Elements in the same group have the same what?","a":"Number of outer-shell electrons","d1":"Mass number","d2":"Number of neutrons","d3":"Number of electron shells","explain":"The same outer-electron count gives similar chemical properties.","topic":"periodic","tier":2,"trap":"Confusing a group with a period, which fixes the number of shells."},{"q":"Which of these is a transition metal?","a":"Iron","d1":"Sodium","d2":"Calcium","d3":"Argon","explain":"Iron sits in the block of transition metals between Groups 2 and 3.","topic":"periodic","tier":2,"trap":"Classifying every metal as an alkali or alkaline earth metal."},{"q":"Which element has atomic number 20?","a":"Calcium","d1":"Argon","d2":"Potassium","d3":"Magnesium","explain":"20 protons is calcium; argon has 18 and potassium has 19.","topic":"periodic","tier":2,"trap":"Confusing the order of argon, potassium and calcium."},{"q":"Why does sodium have a lower melting point than magnesium?","a":"Sodium has fewer delocalised electrons per atom, so its metallic bonding is weaker","d1":"Sodium forms weaker ionic bonds","d2":"Sodium atoms are larger, so the bonds are stronger","d3":"Sodium is a gas at room temperature","explain":"Each magnesium atom contributes two electrons to the delocalised sea, sodium only one.","topic":"periodic","tier":3,"trap":"Assuming larger atoms always mean stronger metallic bonding."},{"q":"What is the trend in atomic radius across a period from left to right?","a":"It decreases","d1":"It increases","d2":"It stays the same","d3":"It changes randomly","explain":"Nuclear charge rises while electrons enter the same shell, pulling them closer.","topic":"periodic","tier":3,"trap":"Applying the down-a-group size trend across a period."},{"q":"Why does chlorine have a higher first ionisation energy than sodium?","a":"Higher nuclear charge and a smaller radius hold the outer electron more strongly","d1":"Chlorine has more electron shells","d2":"Chlorine has fewer protons","d3":"Chlorine's outer electron is further from the nucleus","explain":"Both are in period 3, but chlorine's greater effective nuclear charge binds its outer electrons more tightly.","topic":"periodic","tier":3,"trap":"Thinking a non-metal must have a lower ionisation energy than a metal."},{"q":"Which element has the highest melting point: sodium, magnesium, aluminium or silicon?","a":"Silicon","d1":"Sodium","d2":"Magnesium","d3":"Aluminium","explain":"Silicon is a giant covalent solid; the metals have weaker metallic bonding.","topic":"periodic","tier":3,"trap":"Assuming the most metallic element has the highest melting point."},{"q":"Which element is in the same group as oxygen but in period 3?","a":"Sulfur","d1":"Phosphorus","d2":"Chlorine","d3":"Argon","explain":"Oxygen and sulfur are both in Group 6, also numbered Group 16.","topic":"periodic","tier":3,"trap":"Confusing the period number with the group number."},{"q":"An element has electron configuration 2,8,1. What are its group and period?","a":"Group 1, period 3","d1":"Group 3, period 1","d2":"Group 1, period 2","d3":"Group 2, period 3","explain":"One outer electron means Group 1; three occupied shells means period 3.","topic":"periodic","tier":3,"trap":"Reading the configuration digits as the group number."},{"q":"Why are noble gases so unreactive?","a":"They have full outer electron shells","d1":"They have no electrons","d2":"Their nuclei are full","d3":"They are too heavy to react","explain":"A complete outer shell is a stable configuration, so these atoms rarely gain or lose electrons.","topic":"periodic","tier":3,"trap":"Assuming a full shell means no particles at all."},{"q":"What happens to the melting point of the halogens down Group 7?","a":"It increases","d1":"It decreases","d2":"It stays constant","d3":"It changes with no pattern","explain":"Fluorine and chlorine are gases, bromine is a liquid and iodine is a solid, so melting point rises down the group.","topic":"periodic","tier":3,"trap":"Assuming all halogens are gases at room temperature."},{"q":"What is an ion?","a":"An atom or group of atoms with an electric charge","d1":"An atom with a full outer shell","d2":"A pair of shared electrons","d3":"A molecule made of two elements","explain":"Ions form when atoms gain or lose electrons.","topic":"bonding","tier":1,"trap":"Confusing an ion with a covalent bond or a neutral molecule."},{"q":"What is a covalent bond?","a":"A shared pair of electrons between atoms","d1":"A transfer of electrons from one atom to another","d2":"An attraction between oppositely charged ions","d3":"A bond between metal atoms only","explain":"Non-metal atoms share electron pairs in covalent bonds.","topic":"bonding","tier":1,"trap":"Confusing sharing with the electron transfer of ionic bonding."},{"q":"What is an ionic bond?","a":"The attraction between oppositely charged ions","d1":"A shared pair of electrons","d2":"A bond in which electrons move freely","d3":"A bond between identical atoms","explain":"Metal atoms lose electrons and non-metal atoms gain them, producing ions that attract.","topic":"bonding","tier":1,"trap":"Describing ionic bonding as sharing electrons."},{"q":"What is the formula of sodium chloride?","a":"NaCl","d1":"NaCl2","d2":"Na2Cl","d3":"Na2Cl2","explain":"Na+ and Cl- combine in a 1:1 ratio to balance charge.","topic":"bonding","tier":1,"trap":"Writing a formula without balancing the ion charges."},{"q":"What is the formula of magnesium oxide?","a":"MgO","d1":"MgO2","d2":"Mg2O","d3":"Mg2O2","explain":"Mg2+ and O2- have equal but opposite charges, so one of each balances.","topic":"bonding","tier":1,"trap":"Copying the NaCl 1:1 pattern for the wrong reason rather than checking charge."},{"q":"What is the formula of calcium chloride?","a":"CaCl2","d1":"CaCl","d2":"Ca2Cl","d3":"Ca2Cl2","explain":"Ca2+ needs two Cl- ions, giving CaCl2.","topic":"bonding","tier":1,"trap":"Forgetting the 2+ charge on calcium."},{"q":"Which type of bonding occurs between a metal and a non-metal?","a":"Ionic","d1":"Covalent","d2":"Metallic","d3":"Hydrogen","explain":"Electron transfer between a metal and a non-metal gives ionic bonding.","topic":"bonding","tier":1,"trap":"Assuming all bonds between two different elements are covalent."},{"q":"What holds the atoms together in a metal?","a":"Attraction between positive ions and delocalised electrons","d1":"Shared electron pairs","d2":"Oppositely charged ions","d3":"Neutron bonds","explain":"Metal cations are surrounded by a sea of delocalised electrons.","topic":"bonding","tier":1,"trap":"Describing metallic bonding as ionic or covalent."},{"q":"What is the formula of aluminium oxide?","a":"Al2O3","d1":"AlO","d2":"Al3O2","d3":"Al2O","explain":"Al3+ and O2- need a 2:3 ratio to give a total charge of zero.","topic":"bonding","tier":2,"trap":"Swapping the charges but forgetting to check the final balance."},{"q":"Why does sodium chloride conduct electricity when molten but not when solid?","a":"The ions are free to move when molten but fixed in the solid lattice","d1":"Electrons are shared when molten","d2":"The solid contains no ions","d3":"The bonds break and release atoms","explain":"Conduction requires mobile charged particles; the solid lattice holds ions in place.","topic":"bonding","tier":2,"trap":"Assuming electrons, not ions, carry the current in an ionic melt."},{"q":"Why does magnesium chloride have the formula MgCl2 rather than MgCl?","a":"Magnesium forms 2+ ions, so two chloride ions are needed","d1":"Chlorine forms 2- ions","d2":"Magnesium has two electron shells","d3":"The name ends in -ide","explain":"Charge balance requires two Cl- for each Mg2+.","topic":"bonding","tier":2,"trap":"Using the number of shells instead of the ion charge."},{"q":"What is the formula of potassium sulfate?","a":"K2SO4","d1":"KSO4","d2":"K2SO3","d3":"K(SO4)2","explain":"Two K+ ions balance one SO4 2- ion.","topic":"bonding","tier":2,"trap":"Ignoring the charge on the sulfate ion."},{"q":"Which compound contains both ionic and covalent bonding?","a":"Sodium sulfate","d1":"Sodium chloride","d2":"Methane","d3":"Magnesium oxide","explain":"The bonds within SO4 2- are covalent, while the bonding to Na+ is ionic.","topic":"bonding","tier":2,"trap":"Assuming a compound can use only one bonding type."},{"q":"What is the formula of calcium nitrate?","a":"Ca(NO3)2","d1":"CaNO3","d2":"Ca2NO3","d3":"CaN2O6","explain":"Ca2+ needs two nitrate ions, each NO3-, so the formula is Ca(NO3)2.","topic":"bonding","tier":2,"trap":"Forgetting the brackets around a polyatomic ion."},{"q":"Why do simple molecular substances have low melting points?","a":"Only weak intermolecular forces need to be overcome","d1":"Covalent bonds are weak","d2":"They contain no bonds","d3":"Their atoms are ions","explain":"The strong covalent bonds stay intact; the weak forces between molecules break first.","topic":"bonding","tier":2,"trap":"Saying the covalent bonds themselves are weak."},{"q":"What is the formula of ammonium sulfate?","a":"(NH4)2SO4","d1":"NH4SO4","d2":"NH4(SO4)2","d3":"N2H8SO4","explain":"Two NH4+ ions balance one SO4 2- ion.","topic":"bonding","tier":2,"trap":"Balancing the wrong ion or dropping the brackets."},{"q":"Why is graphite a good conductor of electricity?","a":"Each carbon atom has one delocalised electron","d1":"It contains free ions","d2":"Its covalent bonds are weak","d3":"It has a small surface area","explain":"Three of graphite's four outer electrons form bonds; the fourth is delocalised.","topic":"bonding","tier":3,"trap":"Assuming all four carbon electrons are fixed in bonds, as in diamond."},{"q":"Why does diamond have a very high melting point?","a":"It is a giant covalent lattice with many strong bonds to break","d1":"It contains ions","d2":"It has weak intermolecular forces","d3":"It is a metal","explain":"Every carbon is bonded to four others, so melting requires breaking a network of strong covalent bonds.","topic":"bonding","tier":3,"trap":"Confusing a giant covalent solid with a simple molecular one."},{"q":"Which substance has a giant ionic lattice: sodium chloride, methane, iodine or carbon dioxide?","a":"Sodium chloride","d1":"Methane","d2":"Iodine","d3":"Carbon dioxide","explain":"Ionic compounds form a three-dimensional lattice of alternating ions.","topic":"bonding","tier":3,"trap":"Treating every solid as a giant lattice."},{"q":"Why does magnesium oxide have a higher melting point than sodium chloride?","a":"Its ions carry 2+ and 2- charges, so the electrostatic attraction is stronger","d1":"It has larger ions","d2":"It is covalent","d3":"It contains more atoms","explain":"Doubly charged ions attract more strongly, raising the melting point.","topic":"bonding","tier":3,"trap":"Assuming all ionic compounds have the same lattice strength."},{"q":"What is the formula of iron(III) chloride?","a":"FeCl3","d1":"FeCl2","d2":"Fe3Cl","d3":"Fe2Cl3","explain":"Fe3+ needs three Cl- ions.","topic":"bonding","tier":3,"trap":"Ignoring the Roman numeral and using the 2+ ion."},{"q":"Why is the bond angle in water about 104.5 degrees rather than 109.5?","a":"Two lone pairs repel more strongly than bonding pairs","d1":"Oxygen has no lone pairs","d2":"The O-H bonds are ionic","d3":"Water is a linear molecule","explain":"Lone-pair repulsion compresses the tetrahedral angle.","topic":"bonding","tier":3,"trap":"Assuming all electron pairs repel equally."},{"q":"Why does ammonia have the formula NH3 and not NH4?","a":"A neutral nitrogen atom forms three covalent bonds","d1":"Nitrogen forms only single bonds","d2":"Hydrogen can form only one bond per molecule","d3":"Ammonia is ionic","explain":"Nitrogen has five outer electrons and needs three more, so it shares three pairs.","topic":"bonding","tier":3,"trap":"Confusing the ammonium ion, NH4+, with the neutral molecule."},{"q":"What is the formula of copper(II) nitrate?","a":"Cu(NO3)2","d1":"CuNO3","d2":"Cu2NO3","d3":"Cu(NO3)3","explain":"Cu2+ needs two nitrate ions.","topic":"bonding","tier":3,"trap":"Using the wrong charge for copper or forgetting the bracket."},{"q":"What is the product when magnesium burns in oxygen?","a":"Magnesium oxide","d1":"Magnesium hydroxide","d2":"Magnesium carbonate","d3":"Magnesium chloride","explain":"2Mg + O2 -> 2MgO.","topic":"reactions","tier":1,"trap":"Adding hydrogen or carbon that is not present."},{"q":"What gas is produced when an acid reacts with a metal?","a":"Hydrogen","d1":"Oxygen","d2":"Carbon dioxide","d3":"Chlorine","explain":"Acid + metal -> salt + hydrogen.","topic":"reactions","tier":1,"trap":"Confusing the metal-acid reaction with acid-carbonate."},{"q":"What gas turns limewater milky?","a":"Carbon dioxide","d1":"Hydrogen","d2":"Oxygen","d3":"Nitrogen","explain":"Carbon dioxide forms insoluble calcium carbonate in limewater.","topic":"reactions","tier":1,"trap":"Confusing the test for carbon dioxide with the test for hydrogen."},{"q":"What is the test for hydrogen gas?","a":"A lit splint gives a squeaky pop","d1":"Limewater turns milky","d2":"A glowing splint relights","d3":"Damp litmus turns red","explain":"Hydrogen burns with a characteristic pop.","topic":"reactions","tier":1,"trap":"Using the oxygen test instead."},{"q":"What is the test for oxygen gas?","a":"A glowing splint relights","d1":"A lit splint pops","d2":"Limewater turns milky","d3":"The gas bleaches litmus","explain":"Oxygen supports combustion and relights a glowing splint.","topic":"reactions","tier":1,"trap":"Using the hydrogen test instead."},{"q":"What is the general equation for combustion of a hydrocarbon?","a":"Hydrocarbon + oxygen -> carbon dioxide + water","d1":"Hydrocarbon + oxygen -> carbon monoxide + hydrogen","d2":"Hydrocarbon + water -> carbon dioxide + oxygen","d3":"Hydrocarbon + nitrogen -> ammonia","explain":"Complete combustion oxidises carbon to CO2 and hydrogen to H2O.","topic":"reactions","tier":1,"trap":"Forgetting that hydrogen ends up in water."},{"q":"What is produced when an acid reacts with a carbonate?","a":"A salt, water and carbon dioxide","d1":"A salt and hydrogen","d2":"A salt and oxygen","d3":"A salt only","explain":"Acid + carbonate -> salt + water + CO2.","topic":"reactions","tier":1,"trap":"Confusing carbonates with metals, which give hydrogen."},{"q":"What is the product of the reaction between sodium and chlorine?","a":"Sodium chloride","d1":"Sodium chlorate","d2":"Sodium hydroxide","d3":"Sodium carbonate","explain":"2Na + Cl2 -> 2NaCl.","topic":"reactions","tier":1,"trap":"Adding oxygen from the air."},{"q":"Balance: __H2 + __O2 -> __H2O","a":"2, 1, 2","d1":"1, 1, 2","d2":"2, 2, 2","d3":"1, 2, 2","explain":"2H2 + O2 -> 2H2O balances four H and two O.","topic":"reactions","tier":2,"trap":"Balancing the products but not the oxygen atoms."},{"q":"Balance: __Mg + __O2 -> __MgO","a":"2, 1, 2","d1":"1, 1, 1","d2":"2, 2, 2","d3":"1, 2, 2","explain":"2Mg + O2 -> 2MgO balances both elements.","topic":"reactions","tier":2,"trap":"Writing Mg + O -> MgO, which leaves oxygen unbalanced."},{"q":"Balance: __CH4 + __O2 -> __CO2 + __H2O","a":"1, 2, 1, 2","d1":"1, 1, 1, 1","d2":"2, 2, 1, 2","d3":"1, 2, 2, 1","explain":"CH4 + 2O2 -> CO2 + 2H2O balances C, H and O.","topic":"reactions","tier":2,"trap":"Forgetting the two water molecules needed for four hydrogens."},{"q":"What is the balanced equation for sodium reacting with water?","a":"2Na + 2H2O -> 2NaOH + H2","d1":"Na + H2O -> NaOH + H2","d2":"Na + 2H2O -> NaOH + 2H2","d3":"2Na + H2O -> 2NaOH + H2","explain":"Balancing gives 2Na + 2H2O -> 2NaOH + H2.","topic":"reactions","tier":2,"trap":"Writing a skeleton equation without balancing hydrogen."},{"q":"What is the balanced equation for magnesium reacting with hydrochloric acid?","a":"Mg + 2HCl -> MgCl2 + H2","d1":"Mg + HCl -> MgCl + H2","d2":"Mg + 2HCl -> MgCl2 + 2H2","d3":"2Mg + 2HCl -> 2MgCl + H2","explain":"Magnesium forms MgCl2, so two HCl are needed.","topic":"reactions","tier":2,"trap":"Forgetting magnesium's 2+ charge in the salt."},{"q":"What is the product of thermal decomposition of calcium carbonate?","a":"Calcium oxide and carbon dioxide","d1":"Calcium hydroxide and water","d2":"Calcium and carbon dioxide","d3":"Calcium oxide and water","explain":"CaCO3 -> CaO + CO2 on heating.","topic":"reactions","tier":2,"trap":"Confusing decomposition with the acid-carbonate reaction."},{"q":"Which metal will displace copper from copper sulfate solution?","a":"Zinc","d1":"Silver","d2":"Gold","d3":"Copper","explain":"Zinc is more reactive than copper; silver and gold are less reactive.","topic":"reactions","tier":2,"trap":"Assuming any metal can displace any other."},{"q":"What is the balanced equation for the complete combustion of methane?","a":"CH4 + 2O2 -> CO2 + 2H2O","d1":"CH4 + O2 -> CO2 + H2O","d2":"CH4 + 2O2 -> CO + 2H2O","d3":"CH4 + 3O2 -> CO2 + 3H2O","explain":"Complete combustion gives CO2 and water, balanced as shown.","topic":"reactions","tier":2,"trap":"Producing carbon monoxide and calling it complete combustion."},{"q":"In the equation 2H2 + O2 -> 2H2O, how many moles of water form from 4 moles of H2?","a":"4","d1":"2","d2":"8","d3":"1","explain":"The ratio H2:H2O is 2:2, so 4 mol H2 gives 4 mol H2O.","topic":"reactions","tier":3,"trap":"Using the coefficient 2 as a fixed yield rather than a ratio."},{"q":"In 2Al + Fe2O3 -> Al2O3 + 2Fe, how many moles of aluminium react with 0.5 mol of Fe2O3?","a":"1","d1":"0.5","d2":"2","d3":"4","explain":"The ratio Al:Fe2O3 is 2:1, so 0.5 mol Fe2O3 needs 1 mol Al.","topic":"reactions","tier":3,"trap":"Reading the 2 as applying to the product only."},{"q":"How many moles of oxygen are needed to burn 3 mol of methane completely?","a":"6","d1":"3","d2":"1.5","d3":"12","explain":"CH4 + 2O2 means two moles of O2 per mole of CH4: 3 x 2 = 6.","topic":"reactions","tier":3,"trap":"Using a 1:1 ratio from the unbalanced equation."},{"q":"What mass of MgO forms when 2.4 g of magnesium burns completely? Ar: Mg = 24, O = 16.","a":"4.0 g","d1":"2.4 g","d2":"6.4 g","d3":"1.6 g","explain":"2.4 g Mg is 0.1 mol, giving 0.1 mol MgO of mass 0.1 x 40 = 4.0 g.","topic":"reactions","tier":3,"trap":"Adding the oxygen mass to the wrong molar quantity or ignoring the 1:1 ratio."},{"q":"In the reaction Zn + 2HCl -> ZnCl2 + H2, what mass of hydrogen forms from 0.5 mol of zinc? Ar: H = 1.","a":"1.0 g","d1":"0.5 g","d2":"2.0 g","d3":"0.25 g","explain":"0.5 mol Zn gives 0.5 mol H2, which has mass 0.5 x 2 = 1.0 g.","topic":"reactions","tier":3,"trap":"Using the molar mass of a hydrogen atom rather than H2."},{"q":"What volume of carbon dioxide at room temperature and pressure forms when 0.25 mol of calcium carbonate decomposes? One mole of gas occupies 24 dm3.","a":"6 dm3","d1":"24 dm3","d2":"0.25 dm3","d3":"12 dm3","explain":"CaCO3 gives one mole of CO2 per mole, so 0.25 x 24 = 6 dm3.","topic":"reactions","tier":3,"trap":"Multiplying by 24 twice or using the mass instead of the mole ratio."},{"q":"A reaction has a theoretical yield of 8.0 g but produces 6.0 g. What is the percentage yield?","a":"75%","d1":"80%","d2":"133%","d3":"25%","explain":"6.0 / 8.0 x 100 = 75%.","topic":"reactions","tier":3,"trap":"Dividing the actual yield by the theoretical the wrong way round."},{"q":"A displacement reaction occurs between iron and copper sulfate. Which statement is correct?","a":"Iron is oxidised and copper is reduced","d1":"Iron is reduced and copper is oxidised","d2":"Both are oxidised","d3":"Neither changes oxidation state","explain":"Iron loses electrons to become Fe2+; Cu2+ gains electrons to become copper metal.","topic":"reactions","tier":3,"trap":"Reversing oxidation and reduction."},{"q":"What is the pH of a neutral solution at 25 degrees Celsius?","a":"7","d1":"0","d2":"14","d3":"1","explain":"Pure water is neutral with pH 7.","topic":"acids","tier":1,"trap":"Confusing neutral with the top or bottom of the pH scale."},{"q":"What ion do acids produce in water?","a":"Hydrogen ions, H+","d1":"Hydroxide ions, OH-","d2":"Oxide ions, O2-","d3":"Chloride ions, Cl-","explain":"Acids release H+ ions, which are responsible for acidic properties.","topic":"acids","tier":1,"trap":"Confusing acids with alkalis, which release OH-."},{"q":"What ion do alkalis produce in water?","a":"Hydroxide ions, OH-","d1":"Hydrogen ions, H+","d2":"Carbonate ions, CO3 2-","d3":"Sodium ions, Na+","explain":"Alkalis release OH- ions in aqueous solution.","topic":"acids","tier":1,"trap":"Reversing the ions for acids and alkalis."},{"q":"What colour is universal indicator in a strong acid?","a":"Red","d1":"Green","d2":"Purple","d3":"Blue","explain":"Strong acids give a red colour, around pH 1 to 3.","topic":"acids","tier":1,"trap":"Confusing the acid end of the scale with the alkali end."},{"q":"What is the name of the salt formed by hydrochloric acid and sodium hydroxide?","a":"Sodium chloride","d1":"Sodium nitrate","d2":"Sodium sulfate","d3":"Sodium hydroxide","explain":"HCl supplies Cl-, so the salt is sodium chloride.","topic":"acids","tier":1,"trap":"Naming the salt from the base instead of the acid."},{"q":"What is the name of the salt formed by sulfuric acid and potassium hydroxide?","a":"Potassium sulfate","d1":"Potassium sulfide","d2":"Potassium sulfite","d3":"Potassium hydroxide","explain":"Sulfuric acid gives sulfate salts.","topic":"acids","tier":1,"trap":"Confusing sulfate with sulfide or sulfite."},{"q":"What is the name of the salt formed by nitric acid and calcium hydroxide?","a":"Calcium nitrate","d1":"Calcium nitrite","d2":"Calcium nitride","d3":"Calcium hydroxide","explain":"Nitric acid gives nitrate salts.","topic":"acids","tier":1,"trap":"Confusing nitrate with nitrite."},{"q":"What is the reaction between an acid and a base called?","a":"Neutralisation","d1":"Combustion","d2":"Decomposition","d3":"Displacement","explain":"Neutralisation produces a salt and water.","topic":"acids","tier":1,"trap":"Confusing neutralisation with a displacement reaction."},{"q":"What is the equation for neutralisation of hydrochloric acid with sodium hydroxide?","a":"HCl + NaOH -> NaCl + H2O","d1":"HCl + NaOH -> NaCl + H2","d2":"HCl + NaOH -> NaCl + O2","d3":"2HCl + NaOH -> NaCl2 + H2O","explain":"H+ and OH- combine to form water, leaving NaCl.","topic":"acids","tier":2,"trap":"Producing hydrogen instead of water."},{"q":"What is the balanced equation for hydrochloric acid reacting with calcium carbonate?","a":"2HCl + CaCO3 -> CaCl2 + H2O + CO2","d1":"HCl + CaCO3 -> CaCl + H2O + CO2","d2":"2HCl + CaCO3 -> CaCl2 + H2 + CO2","d3":"HCl + CaCO3 -> CaCl2 + H2O + CO2","explain":"Two HCl are needed for CaCl2, and the products are salt, water and CO2.","topic":"acids","tier":2,"trap":"Forgetting to balance the chloride."},{"q":"What is the balanced equation for sulfuric acid reacting with magnesium?","a":"Mg + H2SO4 -> MgSO4 + H2","d1":"Mg + H2SO4 -> MgSO4 + H2O","d2":"2Mg + H2SO4 -> Mg2SO4 + H2","d3":"Mg + H2SO4 -> MgS + H2O","explain":"A metal plus an acid gives a salt plus hydrogen.","topic":"acids","tier":2,"trap":"Producing water as if the acid were neutralised by a base."},{"q":"What happens to the pH when an acid is diluted with water?","a":"It moves towards 7","d1":"It moves towards 0","d2":"It stays exactly the same","d3":"It moves above 7","explain":"Dilution lowers the H+ concentration, so the pH rises towards neutral.","topic":"acids","tier":2,"trap":"Assuming dilution makes a solution more acidic."},{"q":"Which is a strong acid?","a":"Hydrochloric acid","d1":"Ethanoic acid","d2":"Carbonic acid","d3":"Citric acid","explain":"Hydrochloric acid ionises completely; the others are weak.","topic":"acids","tier":2,"trap":"Treating all acids as equally strong."},{"q":"Which is a weak acid?","a":"Ethanoic acid","d1":"Hydrochloric acid","d2":"Nitric acid","d3":"Sulfuric acid","explain":"Ethanoic acid only partially ionises in water.","topic":"acids","tier":2,"trap":"Assuming every acid ionises completely."},{"q":"What is the salt formed when zinc oxide reacts with nitric acid?","a":"Zinc nitrate","d1":"Zinc nitrite","d2":"Zinc oxide nitrate","d3":"Zinc nitride","explain":"The metal from the base and the anion from the acid give zinc nitrate.","topic":"acids","tier":2,"trap":"Naming the salt from the base's own anion."},{"q":"What is the balanced equation for sodium hydroxide reacting with sulfuric acid?","a":"2NaOH + H2SO4 -> Na2SO4 + 2H2O","d1":"NaOH + H2SO4 -> Na2SO4 + H2O","d2":"NaOH + H2SO4 -> NaHSO4 + H2O","d3":"2NaOH + H2SO4 -> Na2SO4 + H2","explain":"Two hydroxides are needed to neutralise the two acidic protons of H2SO4.","topic":"acids","tier":2,"trap":"Using a 1:1 ratio and leaving one acidic hydrogen unneutralised."},{"q":"Why does a solution of a weak acid have a higher pH than a strong acid of the same concentration?","a":"It is only partially ionised, so fewer H+ ions are released","d1":"It contains no H+ ions","d2":"It is more concentrated","d3":"It reacts with water to make OH-","explain":"Partial ionisation gives a lower H+ concentration and hence a higher pH.","topic":"acids","tier":3,"trap":"Assuming equal concentration always means equal pH."},{"q":"25.0 cm3 of 0.100 mol/dm3 NaOH is neutralised by 20.0 cm3 of HCl. What is the concentration of the HCl?","a":"0.125 mol/dm3","d1":"0.100 mol/dm3","d2":"0.080 mol/dm3","d3":"0.200 mol/dm3","explain":"Moles NaOH = 0.0250 x 0.100 = 0.00250; the 1:1 ratio and 0.0200 dm3 give 0.125 mol/dm3.","topic":"acids","tier":3,"trap":"Dividing by the wrong volume or using the ratio backwards."},{"q":"What volume of 0.200 mol/dm3 NaOH neutralises 25.0 cm3 of 0.100 mol/dm3 HCl?","a":"12.5 cm3","d1":"25.0 cm3","d2":"50.0 cm3","d3":"6.25 cm3","explain":"Moles HCl = 0.00250; at 0.200 mol/dm3 the volume needed is 0.0125 dm3 = 12.5 cm3.","topic":"acids","tier":3,"trap":"Assuming equal volumes neutralise because the ratio is 1:1."},{"q":"A solution has a hydrogen ion concentration of 0.01 mol/dm3. What is its pH?","a":"2","d1":"1","d2":"12","d3":"0.01","explain":"pH = -log10(0.01) = 2.","topic":"acids","tier":3,"trap":"Reading the concentration itself as the pH."},{"q":"A solution of pH 3 is diluted tenfold. What is the new pH?","a":"4","d1":"2","d2":"13","d3":"30","explain":"Tenfold dilution reduces H+ concentration by a factor of ten, raising pH by one.","topic":"acids","tier":3,"trap":"Lowering the pH when the acid is diluted."},{"q":"What is the concentration in mol/dm3 of a solution containing 0.05 mol of solute in 250 cm3?","a":"0.20 mol/dm3","d1":"0.05 mol/dm3","d2":"5.0 mol/dm3","d3":"0.0125 mol/dm3","explain":"250 cm3 = 0.250 dm3; 0.05 / 0.250 = 0.20 mol/dm3.","topic":"acids","tier":3,"trap":"Forgetting to convert cm3 to dm3."},{"q":"Which salt is produced when ammonia is neutralised by nitric acid?","a":"Ammonium nitrate","d1":"Ammonia nitrate","d2":"Ammonium nitrite","d3":"Ammonium nitride","explain":"NH3 + HNO3 -> NH4NO3.","topic":"acids","tier":3,"trap":"Naming the cation from the neutral molecule rather than the ammonium ion."},{"q":"What is the relative formula mass of water? Ar: H = 1, O = 16.","a":"18","d1":"17","d2":"20","d3":"16","explain":"2 x 1 + 16 = 18.","topic":"moles","tier":1,"trap":"Forgetting the two hydrogen atoms."},{"q":"What is the relative formula mass of carbon dioxide? Ar: C = 12, O = 16.","a":"44","d1":"28","d2":"32","d3":"12","explain":"12 + 2 x 16 = 44.","topic":"moles","tier":1,"trap":"Counting only one oxygen atom."},{"q":"What is the relative formula mass of sodium chloride? Ar: Na = 23, Cl = 35.5.","a":"58.5","d1":"35.5","d2":"23","d3":"46","explain":"23 + 35.5 = 58.5.","topic":"moles","tier":1,"trap":"Ignoring the sodium or rounding chlorine to 35."},{"q":"What is the relative formula mass of magnesium oxide? Ar: Mg = 24, O = 16.","a":"40","d1":"24","d2":"16","d3":"48","explain":"24 + 16 = 40.","topic":"moles","tier":1,"trap":"Adding the atomic numbers instead of the masses."},{"q":"How many particles are in one mole of a substance?","a":"6.02 x 10^23","d1":"6.02 x 10^22","d2":"1 x 10^23","d3":"12","explain":"One mole contains the Avogadro number, 6.02 x 10^23, of particles.","topic":"moles","tier":1,"trap":"Using the wrong power of ten."},{"q":"What is the mass of 1 mole of oxygen gas, O2? Ar: O = 16.","a":"32 g","d1":"16 g","d2":"8 g","d3":"64 g","explain":"One mole of O2 contains 2 mol of oxygen atoms: 2 x 16 = 32 g.","topic":"moles","tier":1,"trap":"Using the atomic mass of a single oxygen atom."},{"q":"What is the relative formula mass of calcium carbonate? Ar: Ca = 40, C = 12, O = 16.","a":"100","d1":"68","d2":"56","d3":"84","explain":"40 + 12 + 3 x 16 = 100.","topic":"moles","tier":1,"trap":"Counting only one oxygen atom."},{"q":"What is the relative formula mass of sulfuric acid? Ar: H = 1, S = 32, O = 16.","a":"98","d1":"96","d2":"50","d3":"80","explain":"2 x 1 + 32 + 4 x 16 = 98.","topic":"moles","tier":1,"trap":"Forgetting the hydrogens or one oxygen."},{"q":"How many moles are in 36 g of water? Ar: H = 1, O = 16.","a":"2","d1":"1","d2":"18","d3":"0.5","explain":"36 / 18 = 2 mol.","topic":"moles","tier":2,"trap":"Multiplying mass by molar mass instead of dividing."},{"q":"How many moles are in 44 g of carbon dioxide? Ar: C = 12, O = 16.","a":"1","d1":"2","d2":"44","d3":"0.5","explain":"44 / 44 = 1 mol.","topic":"moles","tier":2,"trap":"Dividing by 22 instead of the molar mass."},{"q":"What is the mass of 0.5 mol of sodium hydroxide? Ar: Na = 23, O = 16, H = 1.","a":"20 g","d1":"40 g","d2":"10 g","d3":"0.5 g","explain":"Molar mass 40; 0.5 x 40 = 20 g.","topic":"moles","tier":2,"trap":"Forgetting to multiply by the number of moles."},{"q":"What is the mass of 2 mol of calcium carbonate? Ar: Ca = 40, C = 12, O = 16.","a":"200 g","d1":"100 g","d2":"50 g","d3":"400 g","explain":"Molar mass 100; 2 x 100 = 200 g.","topic":"moles","tier":2,"trap":"Using half the correct mass."},{"q":"What is the relative formula mass of ammonium sulfate? Ar: N = 14, H = 1, S = 32, O = 16.","a":"132","d1":"114","d2":"66","d3":"98","explain":"2 x 18 + 32 + 64 = 132.","topic":"moles","tier":2,"trap":"Forgetting there are two ammonium ions."},{"q":"What is the relative formula mass of copper(II) sulfate pentahydrate, CuSO4.5H2O? Ar: Cu = 64, S = 32, O = 16, H = 1.","a":"250","d1":"160","d2":"178","d3":"90","explain":"64 + 32 + 64 + 5 x 18 = 250.","topic":"moles","tier":2,"trap":"Ignoring the water of crystallisation."},{"q":"How many moles are in 4.0 g of magnesium? Ar: Mg = 24.","a":"0.167 mol","d1":"96 mol","d2":"6 mol","d3":"24 mol","explain":"4.0 / 24 = 0.167 mol to three significant figures.","topic":"moles","tier":2,"trap":"Multiplying mass by atomic mass instead of dividing."},{"q":"What is the mass of 0.25 mol of oxygen gas, O2? Ar: O = 16.","a":"8 g","d1":"4 g","d2":"16 g","d3":"0.25 g","explain":"Molar mass of O2 is 32; 0.25 x 32 = 8 g.","topic":"moles","tier":2,"trap":"Using 16 g/mol for O2 instead of 32."},{"q":"What mass of sodium chloride forms when 0.2 mol of sodium reacts completely with excess chlorine? Ar: Na = 23, Cl = 35.5.","a":"11.7 g","d1":"5.85 g","d2":"23.4 g","d3":"0.2 g","explain":"0.2 mol NaCl has mass 0.2 x 58.5 = 11.7 g.","topic":"moles","tier":3,"trap":"Using the 2:2 ratio but halving the answer."},{"q":"What mass of carbon dioxide forms when 10 g of calcium carbonate decomposes completely? Ar: Ca = 40, C = 12, O = 16.","a":"4.4 g","d1":"10 g","d2":"44 g","d3":"0.44 g","explain":"10 g CaCO3 is 0.1 mol, giving 0.1 mol CO2 of mass 4.4 g.","topic":"moles","tier":3,"trap":"Multiplying the mass by the molar mass instead of dividing."},{"q":"What mass of water forms when 8.0 g of methane burns completely? Ar: H = 1, C = 12, O = 16.","a":"18 g","d1":"9 g","d2":"8.0 g","d3":"36 g","explain":"8.0 g CH4 is 0.5 mol; CH4 + 2O2 gives 2H2O, so 1.0 mol H2O forms, of mass 18 g.","topic":"moles","tier":3,"trap":"Using a 1:1 product ratio and halving the water."},{"q":"How many moles of hydrogen gas form when 1.2 g of magnesium reacts completely with excess hydrochloric acid? Ar: Mg = 24.","a":"0.05 mol","d1":"0.1 mol","d2":"0.025 mol","d3":"1.2 mol","explain":"1.2 / 24 = 0.05 mol Mg, and the equation gives one mole of H2 per mole of Mg.","topic":"moles","tier":3,"trap":"Forgetting the 1:1 ratio or using the mass directly."},{"q":"What volume of hydrogen at room temperature and pressure forms from 0.10 mol of magnesium reacting with excess acid? One mole of gas occupies 24 dm3.","a":"2.4 dm3","d1":"0.24 dm3","d2":"24 dm3","d3":"4.8 dm3","explain":"0.10 mol Mg gives 0.10 mol H2, occupying 0.10 x 24 = 2.4 dm3.","topic":"moles","tier":3,"trap":"Multiplying the mass by 24 or using a 2:1 ratio."},{"q":"A 2.0 g sample of an impure carbonate is 80% calcium carbonate by mass. How many moles of CaCO3 does it contain? Ar: Ca = 40, C = 12, O = 16.","a":"0.016 mol","d1":"0.02 mol","d2":"0.08 mol","d3":"0.8 mol","explain":"80% of 2.0 g is 1.6 g; 1.6 / 100 = 0.016 mol.","topic":"moles","tier":3,"trap":"Using the whole 2.0 g as pure carbonate."},{"q":"A reaction uses 0.10 mol of CaCO3 and produces 3.5 g of CaO. What is the percentage yield? Ar: Ca = 40, O = 16.","a":"62.5%","d1":"35%","d2":"100%","d3":"87.5%","explain":"Theoretical yield is 0.10 x 56 = 5.6 g; 3.5 / 5.6 x 100 = 62.5%.","topic":"moles","tier":3,"trap":"Dividing by the reactant mass instead of the theoretical yield."},{"q":"What is the concentration in mol/dm3 of 0.50 mol of sodium chloride dissolved in 2.0 dm3 of solution?","a":"0.25 mol/dm3","d1":"1.0 mol/dm3","d2":"0.50 mol/dm3","d3":"4.0 mol/dm3","explain":"0.50 / 2.0 = 0.25 mol/dm3.","topic":"moles","tier":3,"trap":"Multiplying instead of dividing."},{"q":"What are the three states of matter?","a":"Solid, liquid and gas","d1":"Solid, liquid and plasma","d2":"Solid, gas and vapour","d3":"Liquid, gas and steam","explain":"The three common states are solid, liquid and gas.","topic":"states","tier":1,"trap":"Adding a fourth state or confusing a gas with a vapour."},{"q":"Which state has a fixed volume but no fixed shape?","a":"Liquid","d1":"Solid","d2":"Gas","d3":"Plasma","explain":"Liquid particles are close together but can move past each other.","topic":"states","tier":1,"trap":"Confusing the properties of solids and liquids."},{"q":"Which state has neither fixed shape nor fixed volume?","a":"Gas","d1":"Liquid","d2":"Solid","d3":"Crystal","explain":"Gas particles are far apart and fill their container.","topic":"states","tier":1,"trap":"Assuming a gas keeps the volume of its container as its own."},{"q":"What happens to particles when a solid melts?","a":"They gain energy and move more freely","d1":"They lose energy and vibrate less","d2":"They break into atoms","d3":"They disappear","explain":"Melting gives particles enough energy to overcome the forces holding them in place.","topic":"states","tier":1,"trap":"Reversing the energy change of melting and freezing."},{"q":"What is the name of the change from gas to liquid?","a":"Condensation","d1":"Evaporation","d2":"Sublimation","d3":"Melting","explain":"Cooling a gas makes it condense into a liquid.","topic":"states","tier":1,"trap":"Confusing condensation with evaporation."},{"q":"What is the name of the change from solid directly to gas?","a":"Sublimation","d1":"Melting","d2":"Condensation","d3":"Deposition","explain":"Sublimation skips the liquid state, as with dry ice.","topic":"states","tier":1,"trap":"Confusing sublimation with melting or boiling."},{"q":"What is the name of the change from liquid to gas?","a":"Evaporation or boiling","d1":"Condensation","d2":"Melting","d3":"Freezing","explain":"Liquid to gas is evaporation when it happens at the surface and boiling when it happens throughout.","topic":"states","tier":1,"trap":"Reversing the direction of the change."},{"q":"What happens to the arrangement of particles when a gas is compressed?","a":"The particles are pushed closer together","d1":"The particles get smaller","d2":"The particles lose their electrons","d3":"The particles turn into a liquid","explain":"Gas particles are widely spaced, so they can be squeezed closer.","topic":"states","tier":1,"trap":"Thinking the particles themselves shrink under pressure."},{"q":"Why does a gas exert pressure on its container?","a":"Particles collide with the container walls","d1":"Particles dissolve in the walls","d2":"Particles are repelled by each other","d3":"Particles lose energy at the walls","explain":"Each collision exerts a tiny force; the sum over many collisions is pressure.","topic":"states","tier":2,"trap":"Thinking pressure comes from particles attracting the walls."},{"q":"What happens to gas pressure when temperature increases at constant volume?","a":"It increases","d1":"It decreases","d2":"It stays the same","d3":"It becomes zero","explain":"Hotter particles move faster and collide with the walls more often and harder.","topic":"states","tier":2,"trap":"Assuming temperature has no effect on pressure."},{"q":"What happens to gas pressure when volume increases at constant temperature?","a":"It decreases","d1":"It increases","d2":"It stays the same","d3":"It doubles","explain":"Fewer wall collisions per unit area give a lower pressure.","topic":"states","tier":2,"trap":"Applying the temperature-pressure trend to volume."},{"q":"Why does a liquid evaporate even below its boiling point?","a":"Some surface particles have enough energy to escape","d1":"All particles boil at once","d2":"The liquid reacts with air","d3":"The liquid loses its bonds","explain":"Evaporation happens from the surface when faster particles escape.","topic":"states","tier":2,"trap":"Assuming evaporation only occurs at the boiling point."},{"q":"Why does evaporation cool the remaining liquid?","a":"The fastest particles leave, lowering the average energy","d1":"The slowest particles leave","d2":"The liquid gains energy from the air","d3":"The liquid freezes","explain":"Removing high-energy particles reduces the average kinetic energy.","topic":"states","tier":2,"trap":"Thinking the particles left behind speed up."},{"q":"Why does a solid keep its shape?","a":"Particles are held in fixed positions by strong forces","d1":"Particles cannot move at all","d2":"Particles are far apart","d3":"Particles are charged","explain":"Solid particles vibrate about fixed positions but do not move past each other.","topic":"states","tier":2,"trap":"Thinking solid particles are completely stationary."},{"q":"Which change of state releases energy to the surroundings?","a":"Condensation","d1":"Boiling","d2":"Melting","d3":"Sublimation","explain":"Gas particles lose energy as they come together to form a liquid.","topic":"states","tier":2,"trap":"Treating every change of state as energy-absorbing."},{"q":"What is the name of the change from gas directly to solid?","a":"Deposition","d1":"Sublimation","d2":"Condensation","d3":"Freezing","explain":"Deposition is the reverse of sublimation.","topic":"states","tier":2,"trap":"Confusing deposition with condensation, which passes through a liquid."},{"q":"How does the spacing of particles compare in a solid, a liquid and a gas?","a":"Solid particles are closest, gas particles furthest apart","d1":"Gas particles are closest","d2":"Liquid particles are furthest apart","d3":"All three have the same spacing","explain":"Particle spacing increases from solid to liquid to gas.","topic":"states","tier":3,"trap":"Reversing the order of particle spacing."},{"q":"A gas at 2.0 atm occupies 3.0 dm3. What volume does it occupy at 4.0 atm at constant temperature?","a":"1.5 dm3","d1":"6.0 dm3","d2":"3.0 dm3","d3":"0.67 dm3","explain":"p1V1 = p2V2 gives 2.0 x 3.0 / 4.0 = 1.5 dm3.","topic":"states","tier":3,"trap":"Multiplying pressure and volume instead of using the inverse relationship."},{"q":"A gas at 300 K and 1.0 atm is heated to 600 K at constant volume. What is the new pressure?","a":"2.0 atm","d1":"0.5 atm","d2":"1.0 atm","d3":"600 atm","explain":"Pressure is proportional to temperature in kelvin: doubling T doubles p.","topic":"states","tier":3,"trap":"Using Celsius instead of kelvin or inverting the ratio."},{"q":"A gas occupies 240 cm3 at 300 K. What volume does it occupy at 200 K at constant pressure?","a":"160 cm3","d1":"360 cm3","d2":"320 cm3","d3":"80 cm3","explain":"V is proportional to T, so 240 x 200/300 = 160 cm3.","topic":"states","tier":3,"trap":"Increasing the volume as the gas cools."},{"q":"Why does the pressure of a fixed mass of gas rise when it is heated at constant volume?","a":"Faster particles collide with the walls more often and more forcefully","d1":"The particles get larger","d2":"The number of particles increases","d3":"The walls contract","explain":"Heating raises average kinetic energy, increasing both collision frequency and force.","topic":"states","tier":3,"trap":"Thinking heating creates extra gas particles."},{"q":"Why does the temperature stay constant while ice melts at 0 degrees Celsius?","a":"Energy is used to overcome forces between particles, not to raise kinetic energy","d1":"The ice is at absolute zero","d2":"No energy is supplied","d3":"The water boils immediately","explain":"Latent heat breaks the lattice without changing temperature.","topic":"states","tier":3,"trap":"Assuming all added energy must raise the temperature."},{"q":"A sample of gas is cooled from 400 K to 200 K at constant pressure. What happens to its volume?","a":"It halves","d1":"It doubles","d2":"It stays the same","d3":"It quadruples","explain":"Volume is proportional to temperature, so halving T halves V.","topic":"states","tier":3,"trap":"Assuming volume is independent of temperature."},{"q":"Why does a gas diffuse faster at higher temperature?","a":"Particles have higher average speed","d1":"Particles become smaller","d2":"The gas becomes denser","d3":"The container expands","explain":"Kinetic theory gives higher speed at higher temperature, so particles spread faster.","topic":"states","tier":3,"trap":"Confusing diffusion speed with particle size."},{"q":"A balloon expands as it rises. Which explanation is correct?","a":"External pressure falls, so the gas occupies a larger volume","d1":"The gas particles multiply","d2":"The gas cools and contracts","d3":"The balloon material dissolves","explain":"At constant temperature, lower pressure means larger volume.","topic":"states","tier":3,"trap":"Assuming rising always means cooling and contracting."},{"q":"Which method separates a mixture of sand and water?","a":"Filtration","d1":"Distillation","d2":"Chromatography","d3":"Evaporation to dryness","explain":"Filtration traps the insoluble solid while the liquid passes through.","topic":"separating","tier":1,"trap":"Using distillation for an insoluble solid."},{"q":"Which method separates a mixture of salt and water to recover the water?","a":"Simple distillation","d1":"Filtration","d2":"Chromatography","d3":"Decanting","explain":"Distillation evaporates the water and condenses it in a cooler.","topic":"separating","tier":1,"trap":"Using evaporation, which loses the water."},{"q":"What is the name of the solid that remains on filter paper?","a":"Residue","d1":"Filtrate","d2":"Distillate","d3":"Solute","explain":"The residue is trapped by the filter; the liquid that passes through is the filtrate.","topic":"separating","tier":1,"trap":"Confusing the residue with the filtrate."},{"q":"What is the liquid that passes through filter paper called?","a":"Filtrate","d1":"Residue","d2":"Distillate","d3":"Solvent","explain":"The filtrate is the liquid collected after filtration.","topic":"separating","tier":1,"trap":"Confusing the filtrate with the residue."},{"q":"Which method separates coloured dyes in ink?","a":"Chromatography","d1":"Filtration","d2":"Distillation","d3":"Crystallisation","explain":"Different dyes travel different distances on the paper.","topic":"separating","tier":1,"trap":"Using a method that separates by particle size only."},{"q":"What is the name of the liquid collected in distillation?","a":"Distillate","d1":"Residue","d2":"Filtrate","d3":"Precipitate","explain":"The condensed vapour collected is the distillate.","topic":"separating","tier":1,"trap":"Confusing the distillate with the residue left in the flask."},{"q":"Which method would you use to separate ethanol from water?","a":"Fractional distillation","d1":"Filtration","d2":"Chromatography","d3":"Decanting","explain":"The liquids have different boiling points and are separated by fractional distillation.","topic":"separating","tier":1,"trap":"Choosing a method for insoluble solids."},{"q":"What is a mixture?","a":"Two or more substances not chemically combined","d1":"A compound of two elements","d2":"A pure element","d3":"A single atom","explain":"Mixtures can be separated by physical methods because their components are not chemically bonded.","topic":"separating","tier":1,"trap":"Confusing a mixture with a compound."},{"q":"Which method recovers a dissolved solid from its solution?","a":"Crystallisation","d1":"Filtration","d2":"Chromatography","d3":"Distillation","explain":"Evaporating some solvent and cooling produces crystals.","topic":"separating","tier":2,"trap":"Using filtration, which does not remove dissolved solids."},{"q":"Why is filtration unsuitable for separating salt from water?","a":"Dissolved salt passes through the filter with the water","d1":"Salt is too large to pass through","d2":"Water dissolves the filter paper","d3":"Salt floats on water","explain":"Filtration separates particles by size and cannot trap dissolved ions.","topic":"separating","tier":2,"trap":"Assuming dissolved particles are large enough to be filtered."},{"q":"In chromatography, what does an Rf value represent?","a":"Distance travelled by the spot divided by distance travelled by the solvent","d1":"Distance travelled by the solvent divided by the spot distance","d2":"The mass of the dye","d3":"The boiling point of the solvent","explain":"Rf = distance moved by the substance / distance moved by the solvent front.","topic":"separating","tier":2,"trap":"Inverting the Rf ratio."},{"q":"Why is the solvent front marked before the chromatogram dries?","a":"The solvent evaporates, so the front is no longer visible","d1":"The dyes change colour","d2":"The paper shrinks","d3":"The Rf value changes","explain":"The solvent front must be recorded while the wet line can be seen.","topic":"separating","tier":2,"trap":"Assuming the solvent line stays visible indefinitely."},{"q":"Which mixture can be separated by simple distillation?","a":"A solution of copper sulfate in water","d1":"Sand and gravel","d2":"Oil and water","d3":"Two dyes in ink","explain":"A dissolved salt and water separate by boiling point.","topic":"separating","tier":2,"trap":"Choosing distillation for a mixture of two immiscible liquids."},{"q":"Why are the fractions in fractional distillation collected at different heights?","a":"They condense at different temperatures along the column","d1":"They have different colours","d2":"They are filtered at each level","d3":"They have different densities only","explain":"The temperature gradient in the column condenses each fraction at its own boiling range.","topic":"separating","tier":2,"trap":"Assuming separation depends on colour or density alone."},{"q":"What is the purpose of a fractionating column?","a":"To separate liquids with different boiling points","d1":"To filter solid particles","d2":"To dissolve solids","d3":"To cool a single liquid","explain":"The column provides a temperature gradient for repeated condensation and evaporation.","topic":"separating","tier":2,"trap":"Confusing fractional distillation with filtration."},{"q":"Which technique is best for separating a mixture of two miscible liquids with close boiling points?","a":"Fractional distillation","d1":"Simple distillation","d2":"Filtration","d3":"Crystallisation","explain":"Fractional distillation gives a better separation for close boiling points.","topic":"separating","tier":2,"trap":"Choosing simple distillation when the boiling points are too close."},{"q":"A spot moves 3.0 cm while the solvent front moves 12.0 cm. What is the Rf value?","a":"0.25","d1":"4.0","d2":"0.75","d3":"12","explain":"Rf = 3.0 / 12.0 = 0.25.","topic":"separating","tier":3,"trap":"Dividing the wrong way round."},{"q":"A spot moves 4.0 cm and has Rf 0.50. How far did the solvent front move?","a":"8.0 cm","d1":"2.0 cm","d2":"4.5 cm","d3":"0.125 cm","explain":"Solvent distance = 4.0 / 0.50 = 8.0 cm.","topic":"separating","tier":3,"trap":"Multiplying by the Rf instead of dividing."},{"q":"Two dyes have Rf values 0.35 and 0.72. Which one is more soluble in the solvent?","a":"The one with Rf 0.72","d1":"The one with Rf 0.35","d2":"Both are equally soluble","d3":"Solubility cannot be compared","explain":"A higher Rf means the substance travels further with the solvent, so it is more soluble.","topic":"separating","tier":3,"trap":"Assuming a low Rf means high solubility."},{"q":"Why is the baseline drawn in pencil rather than ink?","a":"Ink would dissolve and add its own spots","d1":"Pencil is easier to see","d2":"Ink is too thick","d3":"Pencil repels the solvent","explain":"Ink contains dyes that would run and contaminate the chromatogram.","topic":"separating","tier":3,"trap":"Thinking the pencil mark affects the Rf calculation."},{"q":"A student obtains Rf 0.50 for a dye and 0.50 for a known standard. What can be concluded?","a":"The dye is likely the same substance as the standard","d1":"The dye is definitely a different substance","d2":"The dye is a mixture of two substances","d3":"The Rf value proves the mass","explain":"Matching Rf values in the same solvent suggest the same substance, though other evidence may be needed.","topic":"separating","tier":3,"trap":"Treating an Rf match as proof of identity in every case."},{"q":"Why is crystallisation preferred over evaporation to dryness for copper sulfate?","a":"Evaporation to dryness would decompose the hydrated crystals","d1":"Evaporation is too slow","d2":"Crystallisation removes all water","d3":"Copper sulfate is insoluble","explain":"Gentle crystallisation preserves the water of crystallisation, which heating would drive off.","topic":"separating","tier":3,"trap":"Assuming evaporation to dryness always gives purer crystals."},{"q":"Why does fractional distillation of crude oil separate it into fractions rather than pure compounds?","a":"Each fraction is a mixture with a range of boiling points","d1":"Crude oil is a pure substance","d2":"The column removes all impurities","d3":"All fractions have the same boiling point","explain":"Fractions group hydrocarbons with similar but not identical boiling points.","topic":"separating","tier":3,"trap":"Treating each fraction as a single pure compound."},{"q":"A mixture of ethanol and water is distilled. Why is the first distillate richer in ethanol?","a":"Ethanol has the lower boiling point and vaporises first","d1":"Ethanol is denser","d2":"Water evaporates first","d3":"Ethanol is insoluble in water","explain":"The component with the lower boiling point is enriched in the early vapour.","topic":"separating","tier":3,"trap":"Reversing which component boils first."},{"q":"In an exothermic reaction, what happens to the energy of the surroundings?","a":"It increases","d1":"It decreases","d2":"It stays the same","d3":"It becomes zero","explain":"Exothermic reactions transfer energy to the surroundings, usually as heat.","topic":"energetics","tier":1,"trap":"Reversing exothermic and endothermic."},{"q":"What is an endothermic reaction?","a":"One that takes in energy from the surroundings","d1":"One that releases energy to the surroundings","d2":"One that needs no energy to start","d3":"One that produces light only","explain":"Endothermic reactions absorb energy, often causing a temperature drop.","topic":"energetics","tier":1,"trap":"Reversing the definition of endothermic."},{"q":"Which process is endothermic?","a":"Thermal decomposition of calcium carbonate","d1":"Combustion of methane","d2":"Neutralisation of an acid with an alkali","d3":"Condensation of steam","explain":"Heating CaCO3 to decompose it requires a continuous energy input.","topic":"energetics","tier":1,"trap":"Assuming any reaction that needs heating releases energy."},{"q":"What is activation energy?","a":"The minimum energy needed for a reaction to start","d1":"The energy released when bonds form","d2":"The total energy of the products","d3":"The energy stored in the catalyst","explain":"Particles must collide with at least this energy for a reaction to occur.","topic":"energetics","tier":1,"trap":"Confusing the starting barrier with the overall energy change."},{"q":"On an energy profile, what does the difference between reactants and products show?","a":"The overall energy change of the reaction","d1":"The activation energy","d2":"The rate of reaction","d3":"The mass of the products","explain":"The vertical gap between the two energy levels is the enthalpy change.","topic":"energetics","tier":1,"trap":"Reading the overall change as the activation barrier."},{"q":"A reaction that releases heat has what sign of enthalpy change?","a":"Negative","d1":"Positive","d2":"Zero","d3":"It has no sign","explain":"Energy leaves the system, so the enthalpy change is negative.","topic":"energetics","tier":1,"trap":"Giving a releasing reaction a positive sign."},{"q":"Combustion of a fuel is what type of reaction?","a":"Exothermic","d1":"Endothermic","d2":"Neutralisation","d3":"Decomposition","explain":"Burning releases energy to the surroundings.","topic":"energetics","tier":1,"trap":"Classifying combustion as energy-absorbing."},{"q":"Photosynthesis is what type of reaction?","a":"Endothermic","d1":"Exothermic","d2":"Neutralisation","d3":"Displacement","explain":"Plants absorb light energy to build glucose from carbon dioxide and water.","topic":"energetics","tier":1,"trap":"Assuming all natural reactions release energy."},{"q":"What happens to the temperature of the surroundings during an endothermic reaction?","a":"It decreases","d1":"It increases","d2":"It stays constant","d3":"It doubles","explain":"The reaction absorbs energy, so the surroundings lose heat.","topic":"energetics","tier":2,"trap":"Applying the exothermic temperature change to an endothermic one."},{"q":"Is breaking a chemical bond endothermic or exothermic?","a":"Endothermic","d1":"Exothermic","d2":"Neither","d3":"It depends only on the element","explain":"Energy must be supplied to break a bond.","topic":"energetics","tier":2,"trap":"Confusing bond breaking with bond forming."},{"q":"Is forming a chemical bond endothermic or exothermic?","a":"Exothermic","d1":"Endothermic","d2":"Neither","d3":"It depends only on the element","explain":"Energy is released when a bond forms.","topic":"energetics","tier":2,"trap":"Reversing the energy change for bond formation."},{"q":"Why is a reaction exothermic overall?","a":"More energy is released forming bonds than is absorbed breaking bonds","d1":"More energy is absorbed breaking bonds than released forming bonds","d2":"No bonds are broken","d3":"The catalyst supplies the energy","explain":"The net balance of bond breaking and forming determines the sign of the energy change.","topic":"energetics","tier":2,"trap":"Comparing the two energy terms the wrong way round."},{"q":"Which of these is a renewable fuel?","a":"Bioethanol","d1":"Petrol","d2":"Diesel","d3":"Coal","explain":"Bioethanol is produced from crops that can be regrown.","topic":"energetics","tier":2,"trap":"Treating all liquid fuels as renewable."},{"q":"What does a catalyst do to a reaction?","a":"Speeds it up without being used up","d1":"Changes the products","d2":"Increases the energy released","d3":"Raises the activation energy","explain":"A catalyst lowers the activation energy and is recovered unchanged.","topic":"energetics","tier":2,"trap":"Thinking a catalyst changes the thermodynamics of the reaction."},{"q":"Does a catalyst change the overall energy change of a reaction?","a":"No, it only lowers the activation energy","d1":"Yes, it increases the energy released","d2":"Yes, it makes the reaction endothermic","d3":"Yes, it removes the activation energy completely","explain":"The reactants and products are unchanged, so the energy change is unchanged.","topic":"energetics","tier":2,"trap":"Confusing a lower barrier with a larger energy release."},{"q":"On an energy profile for an exothermic reaction, how do the products compare with the reactants?","a":"The products are lower in energy","d1":"The products are higher in energy","d2":"They are at the same energy","d3":"The products have no energy","explain":"Energy is released, so the product level sits below the reactant level.","topic":"energetics","tier":2,"trap":"Drawing an exothermic profile with products above reactants."},{"q":"How much energy is released when 2 mol of a fuel burns, given an energy release of 890 kJ per mole?","a":"1780 kJ","d1":"890 kJ","d2":"445 kJ","d3":"3560 kJ","explain":"2 x 890 = 1780 kJ.","topic":"energetics","tier":3,"trap":"Forgetting to scale by the number of moles."},{"q":"How much energy is released when 0.5 mol of a fuel burns, given 400 kJ per mole?","a":"200 kJ","d1":"400 kJ","d2":"800 kJ","d3":"0.5 kJ","explain":"0.5 x 400 = 200 kJ.","topic":"energetics","tier":3,"trap":"Doubling instead of halving."},{"q":"A fuel releases 1200 kJ when 0.25 mol burns. What is the energy release per mole?","a":"4800 kJ/mol","d1":"300 kJ/mol","d2":"1200 kJ/mol","d3":"0.25 kJ/mol","explain":"1200 / 0.25 = 4800 kJ/mol.","topic":"energetics","tier":3,"trap":"Multiplying by the number of moles."},{"q":"Why does a catalyst increase the rate of a reaction?","a":"It provides an alternative pathway with lower activation energy","d1":"It increases the temperature","d2":"It increases the concentration of reactants","d3":"It makes the reaction exothermic","explain":"More particles have enough energy to react once the barrier is lowered.","topic":"energetics","tier":3,"trap":"Thinking a catalyst raises the particle energies."},{"q":"Why is a reaction with a high activation energy slow at room temperature?","a":"Few particles have enough energy to overcome the barrier","d1":"The products are unstable","d2":"The reaction is always endothermic","d3":"The reactants are too concentrated","explain":"Only the high-energy tail of the collision distribution can react.","topic":"energetics","tier":3,"trap":"Assuming a high barrier means the reaction cannot happen at all."},{"q":"A reaction has an activation energy of 50 kJ/mol and releases 80 kJ/mol. What is the energy of the products relative to the reactants?","a":"80 kJ/mol lower","d1":"50 kJ/mol lower","d2":"80 kJ/mol higher","d3":"130 kJ/mol lower","explain":"The overall change is the release, 80 kJ/mol, independent of the barrier height.","topic":"energetics","tier":3,"trap":"Adding the activation energy to the overall change."},{"q":"Why does increasing temperature increase reaction rate?","a":"More particles have energy above the activation energy and collide more often","d1":"The activation energy decreases","d2":"The particles become smaller","d3":"The products are removed faster","explain":"Both collision frequency and the fraction of successful collisions rise.","topic":"energetics","tier":3,"trap":"Claiming that heating lowers the activation energy."},{"q":"Why is the energy change measured in a solution calorimetry experiment often lower than the theoretical value?","a":"Heat is lost to the surroundings and the apparatus","d1":"The reaction does not occur","d2":"The thermometer adds energy","d3":"The molar mass is wrong","explain":"Incomplete insulation loses some released heat before it is measured.","topic":"energetics","tier":3,"trap":"Assuming every experiment captures all the energy released."},{"q":"What is a hydrocarbon?","a":"A compound containing only carbon and hydrogen","d1":"A compound containing carbon, hydrogen and oxygen","d2":"A mixture of carbon and hydrogen","d3":"Any fuel","explain":"Hydrocarbons contain no other elements.","topic":"organic","tier":1,"trap":"Including oxygen in the definition."},{"q":"What is the general formula for alkanes?","a":"CnH2n+2","d1":"CnH2n","d2":"CnH2n-2","d3":"CnHn","explain":"Alkanes are saturated, with two hydrogen atoms per carbon plus two extra.","topic":"organic","tier":1,"trap":"Using the alkene formula for alkanes."},{"q":"What is the general formula for alkenes?","a":"CnH2n","d1":"CnH2n+2","d2":"CnH2n-2","d3":"CnHn","explain":"One double bond removes two hydrogens compared with the alkane.","topic":"organic","tier":1,"trap":"Using the alkane formula for alkenes."},{"q":"What is the name of CH4?","a":"Methane","d1":"Ethane","d2":"Propane","d3":"Methanol","explain":"One carbon with four hydrogens is methane.","topic":"organic","tier":1,"trap":"Miscounting the carbon chain length."},{"q":"What is the name of C2H6?","a":"Ethane","d1":"Methane","d2":"Ethene","d3":"Ethanol","explain":"Two carbons with single bonds and six hydrogens is ethane.","topic":"organic","tier":1,"trap":"Confusing ethane with ethene, which has a double bond."},{"q":"What is the name of C3H8?","a":"Propane","d1":"Butane","d2":"Propene","d3":"Pentane","explain":"Three carbons gives propane.","topic":"organic","tier":1,"trap":"Using the wrong prefix for three carbons."},{"q":"What is the name of C2H4?","a":"Ethene","d1":"Ethane","d2":"Ethyne","d3":"Ethanol","explain":"Two carbons with a double bond gives ethene.","topic":"organic","tier":1,"trap":"Confusing ethene with ethane."},{"q":"What is the test for an alkene?","a":"Bromine water is decolourised","d1":"Limewater turns milky","d2":"A lit splint pops","d3":"Universal indicator turns red","explain":"The double bond adds bromine, removing the orange colour.","topic":"organic","tier":1,"trap":"Using the test for carbon dioxide."},{"q":"What is a saturated hydrocarbon?","a":"One with only single carbon-carbon bonds","d1":"One with a carbon-carbon double bond","d2":"One containing oxygen","d3":"One that has been burned","explain":"Saturated means the carbon atoms are bonded to as many atoms as possible.","topic":"organic","tier":2,"trap":"Calling an alkene saturated because it has hydrogen."},{"q":"What is the product when hydrogen adds to ethene?","a":"Ethane","d1":"Ethanol","d2":"Ethene","d3":"Carbon dioxide","explain":"C2H4 + H2 -> C2H6.","topic":"organic","tier":2,"trap":"Adding water instead of hydrogen."},{"q":"What is cracking?","a":"Breaking large hydrocarbon molecules into smaller ones","d1":"Joining small molecules into polymers","d2":"Burning hydrocarbons completely","d3":"Adding hydrogen to an alkene","explain":"Cracking uses heat and often a catalyst to produce shorter, more useful chains.","topic":"organic","tier":2,"trap":"Confusing cracking with polymerisation."},{"q":"What type of reaction is cracking?","a":"Thermal decomposition","d1":"Neutralisation","d2":"Addition","d3":"Combustion","explain":"Large molecules decompose under heat into smaller molecules.","topic":"organic","tier":2,"trap":"Classifying cracking as combustion."},{"q":"What is a polymer?","a":"A large molecule made from many small repeating units","d1":"A small molecule with one functional group","d2":"A mixture of two elements","d3":"A single atom with a double bond","explain":"Monomers join repeatedly to form a long chain.","topic":"organic","tier":2,"trap":"Confusing a polymer with a small molecule."},{"q":"What is the monomer of poly(ethene)?","a":"Ethene","d1":"Ethane","d2":"Ethanol","d3":"Propene","explain":"The double bond of ethene opens to link the units.","topic":"organic","tier":2,"trap":"Choosing the saturated alkane instead of the alkene."},{"q":"What is the difference between an alkane and an alkene?","a":"An alkene has a carbon-carbon double bond","d1":"An alkane has a carbon-carbon double bond","d2":"An alkene contains oxygen","d3":"An alkane contains only hydrogen","explain":"The double bond is the defining feature of alkenes.","topic":"organic","tier":2,"trap":"Reversing which series has the double bond."},{"q":"What is the product of bromine reacting with ethene?","a":"Dibromoethane","d1":"Bromoethane","d2":"Bromoethene","d3":"Ethane","explain":"One bromine atom adds to each carbon of the double bond, giving C2H4Br2.","topic":"organic","tier":2,"trap":"Adding only one bromine atom."},{"q":"An alkene has 6 carbon atoms. What is its molecular formula?","a":"C6H12","d1":"C6H14","d2":"C6H10","d3":"C6H6","explain":"CnH2n with n = 6 gives C6H12.","topic":"organic","tier":3,"trap":"Adding the two extra hydrogens of an alkane."},{"q":"A hydrocarbon contains 4 carbon atoms and 8 hydrogen atoms. Is it an alkane or an alkene?","a":"An alkene, because it fits CnH2n","d1":"An alkane, because it fits CnH2n+2","d2":"Neither, because it contains oxygen","d3":"An alcohol","explain":"C4H8 matches the alkene formula.","topic":"organic","tier":3,"trap":"Checking the formula against the wrong general formula."},{"q":"Why does ethene decolourise bromine water while ethane does not?","a":"Ethene has a double bond that can add bromine","d1":"Ethane has a double bond","d2":"Ethene is a gas","d3":"Ethane is more reactive","explain":"The C=C bond undergoes addition; the single bonds of ethane do not.","topic":"organic","tier":3,"trap":"Thinking the physical state causes the colour change."},{"q":"Why is cracking useful industrially?","a":"It produces shorter hydrocarbons that are in greater demand as fuels and feedstock","d1":"It removes all carbon","d2":"It converts alkanes to elements","d3":"It makes hydrocarbons unreactive","explain":"Long chains are less useful than the shorter alkenes and fuels cracking produces.","topic":"organic","tier":3,"trap":"Assuming cracking is used to make longer molecules."},{"q":"In the addition polymerisation of ethene, what happens to the double bond?","a":"It opens to form single bonds linking the monomers","d1":"It stays unchanged","d2":"It becomes a triple bond","d3":"It gains oxygen","explain":"Each double bond converts to two single bonds in the polymer backbone.","topic":"organic","tier":3,"trap":"Thinking the double bond survives polymerisation."},{"q":"Why do addition polymers have the same empirical formula as their monomers?","a":"No atoms are lost when the monomers join","d1":"Water is removed","d2":"The monomers lose hydrogen","d3":"The polymer gains oxygen","explain":"Addition polymerisation only rearranges bonds, so the atom ratio is unchanged.","topic":"organic","tier":3,"trap":"Confusing addition with condensation polymerisation."},{"q":"Why do alkenes have a higher reactivity than alkanes?","a":"The carbon-carbon double bond is electron-rich and readily attacked","d1":"Alkenes have weaker carbon-hydrogen bonds","d2":"Alkanes have no electrons","d3":"Alkenes are always gases","explain":"The pi bond in C=C is more easily broken in addition reactions.","topic":"organic","tier":3,"trap":"Attributing alkene reactivity to the C-H bonds."},{"q":"A polymer has the repeating unit -CH2-CH2-. From which monomer is it made?","a":"Ethene","d1":"Ethane","d2":"Ethanol","d3":"Ethyne","explain":"Removing the repeat-unit brackets gives C2H4, which is ethene.","topic":"organic","tier":3,"trap":"Choosing ethane, which would not form the chain."}];
